//We first implement price priority than time priority, that is highest price in buyer side gets to buy
//first and lowest price on seller price gets to sell first, for same price, the one who came
//first gets to buy/sell first. 
//The order will be generated by the TCP gateway which receives the raw bytes

#pragma once
#include <cstddef>
#include <type_traits>
#include "core/types.h"

namespace exchange::matching{

    struct Level;

    struct alignas(64) Order{
        //if possible try out splitting iceberg order and simpler orders for faster performance, right now they are same
        core::OrderId id{0}; // unique identifier for the order
        core::Side side{core::Side::BUY}; // side of the order (buy/sell)
        core::Price price{0}; // price of the order
        core::Quantity qty{0}; // quantity of the order remaining
        core::Quantity original_qty{0}; // original quantity of the order
        core::Quantity display_qty{0}; // quantity of the order to be displayed in the order book(Useful for iceberg orders)
        core::Quantity hidden_qty{0}; // quantity of the order that is hidden from the order book(Useful for iceberg orders)
        core::Quantity peak_qty{0}; // peak quantity of the order(Useful for iceberg orders)
        core::Timestamp timestamp{0}; // timestamp of the order(logical clock)
        core::OrderType type{core::OrderType::LIMIT}; // type of the order (limit/market)
        core::OrderStatus status{core::OrderStatus::NEW}; // status of the order (new/partially filled/filled/cancelled)
        core::ParticipantId participant_id{0}; // unique identifier for the participant who placed the order
        core::Price trigger_price{0}; // trigger price for stop orders
        Order* prev{nullptr}; // pointer to the previous order in the order book
        Order* next{nullptr}; // pointer to the next order in the order
        Level *parent_level{nullptr}; // pointer to the parent level of the order

        [[nodiscard]] bool is_stop_order() const noexcept{
            return type== core::OrderType::STOP || type== core::OrderType::STOP_LIMIT;
        }
    };

    static_assert(sizeof(Order)<=128, "Order should stay compact enough for cache friendly access");
    static_assert(std::is_standard_layout_v<Order>, "Order should be standard layout for cache friendly access");
}